<script setup lang="ts">
type Item = { label: string; count: number }
type Stats = { total: number; annotated: number; measured: number; sources: Item[]; colors: Item[]; groups: { field: string; items: Item[] }[] }
const stats = ref<Stats | null>(null)
const error = ref('')
const titles: Record<string, string> = { asset_type:'Type d’image', subject_type:'Sujet', body_plan:'Morphologie', view:'Vue', pose:'Pose', action:'Action', background_type:'Fond', background_scene:'Décor', render_family:'Rendu', wings:'Ailes', visual_quality:'Qualité', dominant_color_families:'Familles de couleurs', palette_size:'Taille de palette', palette_temperature:'Température', palette_structure:'Structure de palette', palette_contrast:'Contraste' }
const fmt = (n: number) => n.toLocaleString('fr-FR')
onMounted(async () => { try { stats.value = await $fetch<Stats>('/api/catalog-stats') } catch { error.value = 'Impossible de charger les statistiques du dataset.' } })
</script>
<template>
  <main class="explore-shell">
    <header class="explore-header"><NuxtLink to="/" class="brand">IRIS <span>/ DATASET</span></NuxtLink><nav><NuxtLink to="/" class="active">Vue d’ensemble</NuxtLink><NuxtLink to="/galerie">Galerie ↗</NuxtLink></nav></header>
    <section class="hero"><div><p class="kicker">PIXEL ART · DATASET LAB</p><h1>Chaque pixel<br><em>raconte une histoire.</em></h1><p>Explore le corpus, ses couleurs et ses annotations visuelles. Tout commence par les images source.</p><NuxtLink to="/galerie" class="primary-link">Explorer la galerie <span>↗</span></NuxtLink></div><div class="hero-art" aria-hidden="true"><div class="hero-sprite">✳</div><div class="hero-art-caption">UNE COLLECTION,<br>DES MILLIERS D’UNIVERS.</div><span class="art-index">01 / 03</span></div></section>
    <p v-if="error" class="notice">{{ error }}</p><p v-else-if="!stats" class="notice">Calcul des statistiques en cours…</p>
    <template v-if="stats"><section class="metrics"><div><span>IMAGES SOURCE</span><strong>{{ fmt(stats.total) }}</strong><small>dans le catalogue</small></div><div><span>ANNOTATIONS QWEN</span><strong>{{ fmt(stats.annotated) }}</strong><small>{{ (stats.annotated / stats.total * 100).toFixed(1) }} % du catalogue</small></div><div><span>PALETTES MESURÉES</span><strong>{{ fmt(stats.measured) }}</strong><small>parmi les annotations Qwen</small></div></section>
    <section class="section-head"><div><p class="kicker">01 / EXPLORER LES DONNÉES</p><h2>Le dataset en chiffres</h2><p>Les catégories viennent des annotations automatiques Qwen3.8. Leur couverture évolue avec le traitement.</p></div><NuxtLink to="/galerie" class="text-link">Voir les images ↗</NuxtLink></section>
    <section class="dashboard-grid"><article class="dashboard-card"><p class="card-eyebrow">TOUTES LES IMAGES</p><h3>Sources principales</h3><div v-for="item in stats.sources.slice(0, 10)" :key="item.label" class="bar-row"><div><span>{{ item.label.replaceAll('_',' ') }}</span><b>{{ fmt(item.count) }}</b></div><div class="bar-track"><i :style="{width: `${item.count / stats.sources[0]!.count * 100}%`}" /></div></div></article><article class="dashboard-card"><p class="card-eyebrow">{{ fmt(stats.measured) }} PALETTES MESURÉES</p><h3>Couleurs les plus présentes</h3><p class="card-description">Nombre d’images contenant chaque code RGB exact parmi les palettes disponibles.</p><div class="color-rank"><div v-for="item in stats.colors" :key="item.label"><i :style="{background:item.label}" /><span>{{ item.label }}</span><b>{{ fmt(item.count) }}</b></div></div><p v-if="!stats.colors.length" class="card-description">Les palettes sont en cours de calcul.</p></article>
    <article v-for="group in stats.groups" :key="group.field" class="dashboard-card"><p class="card-eyebrow">ANNOTATIONS QWEN3.8</p><h3>{{ titles[group.field] || group.field.replaceAll('_',' ') }}</h3><div v-for="item in group.items" :key="item.label" class="bar-row"><div><span>{{ item.label.replaceAll('_',' ') }}</span><b>{{ fmt(item.count) }}</b></div><div class="bar-track"><i :style="{width: `${item.count / Math.max(1, stats.annotated) * 100}%`}" /></div></div></article></section></template>
    <footer class="explore-footer">IRIS DATASET LAB <span>Explore les détails, un pixel à la fois.</span></footer>
  </main>
</template>
